import pandas as pd

# This fails
try:
    df = pd.read_csv("missing.csv")
except FileNotFoundError as e:
    print(f"Error: {e}")

# Or check first
import os
if os.path.exists("missing.csv"):
    df = pd.read_csv("missing.csv")
else:
    print("File not found!")

